section='Arguments of Death'
add('decumbiture_natal_seventh',289,'you may feare death','death_possibility',['The ascendant at first falling sick is the seventh house at birth.'],'One may fear death.',exceptions=['Unless that year’s profection is the same sign.'],uncertainty=['Profection is referred to the Treatise of Nativities, not defined here.','Historical natal/decumbiture cross-reference within this horary source, not a personal natal claim.'])
