add('combust_lords',290,'undoubtedly declare death','death_testimony',['The ascendant lord and lord of the figure are combust.'],'They undoubtedly declare death.',exceptions=['Unless there is some reception between Sun and them. With that reception and a fortunate Moon, after fear of danger a little hope remains, following the source’s own erratum (PDF888: read feare of danger).'],uncertainty=['Handwriting/strike-through obscures the original phrase. PDF888 identifies the deleted print as all hopes of escape and directs feare of danger; corrected and original layers are recorded separately.','Lord of the Figure is not identified by a selection algorithm in this passage.','Margin handwriting is not promoted to authorial printed text.'])
add('l1_moon_conj_l8',290,'threatens death','death_threat',['Ascendant lord and Moon are conjunct eighth lord.','No interposing aspects of the Fortunes occur.'],'This threatens death.')
add('l8_angle_l1_cadent',290,'is alwayes mortall','death_testimony',['Eighth lord is in an angle.','Ascendant lord is in a cadent house.'],'The source says this is always mortal, the rather if he is an Infortune.',uncertainty=['The pronoun he in the strengthening clause likely concerns eighth lord but is not resolved into an extra required condition.'])
