add('l1_apply_eighth',290,'the Moone being any manner','death_testimony',['Ascendant lord applies to eighth lord OR malevolent planets in the eighth.','Moon is corrupt in any manner.'],'This denotes death.')
add('moon_transfer_eighth',290,'brings usually death','death_testimony',['Moon transfers the light and influence of ascendant lord to eighth lord.'],'This usually brings death.')
add('l8_asc_afflicted',290,'being both afflicted','death_testimony',['Eighth lord is in ascendant.','Ascendant lord and Moon are both afflicted.'],'The source says likewise to the preceding usually-death testimony.',dependencies=['moon_transfer_eighth'],uncertainty=['The nearby usually is carried as the antecedent’s modality rather than silently strengthened to always.'])
add('l1_eighth_weak_moon',290,'It also proves fatall','death_testimony',['Ascendant lord is unfortunate in eighth.','Moon is corrupted OR very weak, and in no essential dignity.'],'This also proves fatal.',uncertainty=['The scope of no essential dignity over the corrupted/very-weak alternative is not fully explicit.'],logic='L1 unfortunate in eighth; Moon “corrupted or very weak, and in no essential Dignity”; preserve alternative and conjunctive phrase without forcing scope.')
add('subterranean_eighth',290,'being Subterranean','death_testimony',['Ascendant lord is subterranean.','He has any aspect to eighth lord in eighth.'],'This argues death.')
