add('l1_joined_bad_lords',290,'it seldome succeeds well','adverse_outcome',['Ascendant lord is corporally joined to fourth, sixth, seventh, OR twelfth lord.'],'This is a very ill sign of life; it seldom succeeds well with the sick person.',uncertainty=['Seldom succeeds well is not converted into inevitable death.'])
add('luminary_time',290,'Luminary of the time','judgment_method',['Judging these illness testimonies.'],'The source directs special consideration of the luminary of the time; according to its good or ill condition one may improve judgment.',uncertainty=['No numeric weighting or override rule is supplied here.'])
add('evil_eighth_peril',[290,291],'great peril of death','death_danger',['Ascendant lord is afflicted by an evil planet in eighth.','No benevolent aspect of Fortunes occurs.','Moon is also vitiated.'],'The source shows great peril of death, usually attributing it to ill government of the sick party or some error in ordering and course of physic.',uncertainty=['The historical blame/treatment attribution is not evidence of actual patient conduct or treatment efficacy.'])
add('first_question_combust',291,'a powerfull argument','death_testimony',['At the first question to the physician, ascendant lord is combust in ascendant.'],'This is a powerful argument that the sick party will die.')
add('l1_l8_unfortunate',291,'prenote death','death_testimony',['Ascendant lord and eighth lord are unfortunate.'],'They prenote death.')
