add('l1_eighth_reception',291,'probable the sick will dye','death_probability',['Ascendant lord is conjunct eighth lord, OR square/conjunct a planet in eighth, OR in eighth lord’s antiscion.','The benevolent sextile OR trine of Jupiter is absent.','Moon is in any way afflicted at the same time.'],'It is probable the sick will die.',exceptions=['If ascendant lord is in reception with the planet in eighth, escape from death is possible; however, a very long and grievous disease cannot be avoided.'],uncertainty=['Reception exception refers to a planet in eighth; its scope over every earlier alternative is not fully restated.','Source probability is qualitative, not a numerical estimate.'])
add('moon_saturn_mars_death',291,'one argument','death_testimony',['Moon is with Saturn OR Mars.','Good aspect assistance from Jupiter and Venus is absent.'],'This is one argument the sick will die then; Saturn being slow or going retrograde makes it worse, and other concurrent testimonies make it more certain.',uncertainty=['The text says from Jupiter and Venus; whether either assistance suffices or both are required is not converted into an executable choice.','The and-if Saturn escalation remains additional rather than silently required in the Mars branch.'],logic='Moon with Saturn/Mars; absence of source-stated Jupiter-and-Venus assistance; IF Saturn slow/retrograde then worse; IF other testimonies concur then more certain.')
add('l1_seventh_fall',291,'these are testimonies of death','death_testimony',['Ascendant lord is in seventh, in his fall, OR under earth in fourth or sixth, OR other cadent houses, afflicted by malevolents.','Eighth lord is in seventh.'],'These are testimonies of death.',uncertainty=['Punctuation does not settle whether in seventh and in his fall are conjunctive, or how affliction scopes over the place alternatives.'],logic='Source sequence: L1 in seventh, in fall, or under earth in fourth/sixth, or other cadents, afflicted by malevolents; AND L8 in seventh. Exact grouping unresolved.')
add('violent_stars',[291,292],'a violent fixed Starre','death_testimony',['A malevolent planet is near the ascending degree, OR a violent fixed star is there.','The source’s examples are Antares in the fourth degree of Sagittarius, Lans/Lanx Australis about the ninth of Scorpio, Palilicium in four Gemini, and Caput Medusae in twenty Taurus.'],'These prenote death.',uncertainty=['Near is not given an orb.','The name printed as Lans/Lanx Australis is not silently corrected; identity spelling remains a paleographic uncertainty.','The stated degrees are historical source coordinates, not present-day positions.','The star list supplies examples rather than an additional requirement that every star be present.'],logic='Malevolent near ascending degree OR violent fixed star there; historical example list is descriptive, not an AND condition.')
