add('lights_saturn_angles',292,'a tedious long sicknesse','duration',['Both Lights are afflicted by Saturn in angles.'],'They testify to a tedious long sickness.',uncertainty=['The angular phrase’s exact attachment is not fully explicit.'])
add('lights_underground',292,'under the earth','duration',['Both Lights are ill dignified and under earth.'],'They signify the same tedious long sickness.',dependencies=['lights_saturn_angles'])
add('sun_afflicted_begin',292,'an extraordinary long sicknesse','death_or_duration',['From the disease’s beginning Sun is corporally afflicted, OR impeded by Saturn/Mars square/opposition, OR in perfect antiscion of a malignant planet, OR applies and does not separate.'],'Either death or extraordinarily long sickness succeeds.',uncertainty=['The target of applying and not separating is not restated; exact scope over preceding alternatives remains unresolved.'],logic='Beginning-of-disease Sun condition: bodily affliction OR Saturn/Mars square/opposition OR perfect antiscion of malignant OR applies-not-separates; last alternative’s object/scope unresolved.')
