issues=[]
def issue(kind,source,gap,keys,disposition='Retain source wording/alternatives; no executable interpretation admitted.',origin='assistant_identified_gap',status='open'):
    ids=[aliases[k] for k in keys]
    pages=sorted({p for r in rules if r['id'] in ids for p in r['pdf_pages']})
    issues.append({'id':f'U-B{len(issues)+1:02d}','type':kind,'origin':origin,'status':status,'source_defined_content':source,'assistant_identified_gap':gap,'affected_candidate_ids':ids,'pdf_pages':pages,'disposition':disposition})
issue('lexical_or_source_tension','The sixth/eighth exchange with sextile/trine says not doubt of the death, then explains Nature is not overcome and the sick shall overcome it.','The historical sense of doubt or textual inconsistency is not settled by this reading.',['six_eight_swap'])
issue('conditional_scope','The Venus/Scorpio clause and female-question branch follow the Moon-sixth/ill-Venus condition; the source uses etc.','Which earlier conditions persist into each branch, and what etc. expands, remain unresolved.',['venus_scorpio','venus_woman'])
